<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$flash='';$err='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();try{$action=(string)($_POST['action']??'');if($action==='add'){mp550_cart_add((int)$_POST['product_id'],max(1,(int)($_POST['qty']??1)));$flash='Product added to cart.';if(!empty($_POST['buy_now'])){header('Location: /checkout.php');exit;}}elseif($action==='update'){foreach((array)($_POST['qty']??[]) as $id=>$q)mp550_cart_set((int)$id,(int)$q);$flash='Cart updated.';}elseif($action==='coupon'){if(!mp550_apply_coupon((string)($_POST['code']??'')))throw new RuntimeException('Coupon is invalid or expired.');$flash='Coupon applied.';}elseif($action==='clear'){mp550_cart_clear();$flash='Cart cleared.';}}catch(Throwable $e){$err=$e->getMessage();}}$cart=mp550_cart_details();mp550_public_header('Shopping Cart');
?>
<section class="mp550-page-head"><div><span>SHOPPING CART</span><h1>Your order, split automatically by seller.</h1><p>You can buy from multiple shops in one checkout. Each seller receives only their own order.</p></div><b><?=mp550_cart_count()?> items</b></section><?php if($flash):?><div class="mp550-alert ok"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="mp550-alert err"><?=e($err)?></div><?php endif;?><section class="mp550-cart-layout"><div class="cart-list"><?php if($cart['items']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><?php foreach($cart['items'] as $it):$p=$it['product'];?><article><div class="thumb"<?=!empty($p['image_url'])?' style="background-image:url(\''.e($p['image_url']).'\')"':''?>></div><div><a href="/product.php?slug=<?=urlencode($p['slug'])?>"><b><?=e($p['title'])?></b></a><small><?=e($p['shop_name']?:$p['seller_name'])?></small><?php if($it['discount']>0):?><em>Discount -<?=mp550_money((float)$it['discount'])?></em><?php endif;?></div><input type="number" name="qty[<?=(int)$p['id']?>]" value="<?=(int)$it['qty']?>" min="0" max="<?=(int)$p['stock']?>"><strong><?=mp550_money((float)$it['line_total'])?></strong></article><?php endforeach;?><button class="mp550-btn ghost">Update cart</button></form><?php else:?><div class="mp550-empty"><b>Your cart is empty</b><span>Explore local products and deals.</span><a class="mp550-btn" href="/shop.php">Start shopping</a></div><?php endif;?></div><aside class="cart-summary"><h2>Order summary</h2><div><span>Subtotal</span><b><?=mp550_money((float)$cart['subtotal'])?></b></div><div><span>Discount</span><b>-<?=mp550_money((float)$cart['discount'])?></b></div><div><span>Shipping</span><b><?=mp550_money((float)$cart['shipping'])?></b></div><div class="total"><span>Total</span><b><?=mp550_money((float)$cart['grand_total'])?></b></div><form method="post" class="coupon"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="coupon"><input name="code" value="<?=e((string)$cart['coupon'])?>" placeholder="Coupon code"><button>Apply</button></form><?php if($cart['items']):?><a class="mp550-btn wide" href="/checkout.php">Proceed to checkout →</a><?php endif;?></aside></section>
<?php mp550_public_footer(); ?>
